import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 27 A wet night","description":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 27 A wet night","description":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 26 The best art critics","link":"/life/english/new-concept/book-2/unit-02/lesson-026"},"next":{"text":"第二册：实践与进步 · Lesson 28 No parking","link":"/life/english/new-concept/book-2/unit-02/lesson-028"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 26 The best art critics","link":"/life/english/new-concept/book-2/unit-02/lesson-026"},"next":{"text":"第二册：实践与进步 · Lesson 28 No parking","link":"/life/english/new-concept/book-2/unit-02/lesson-028"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-027.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-027.md"}'),i={name:"life/english/new-concept/book-2/unit-02/lesson-027.md"};function r(l,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-27-a-wet-night" tabindex="-1">第二册：实践与进步 · Lesson 27 A wet night <a class="header-anchor" href="#第二册-实践与进步-·-lesson-27-a-wet-night" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 27 A wet night&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>露营者刚安顿好，夜间雨水就改变了计划；练习把入睡前的准备与醒来后的发现分层。本课的语言观察是：had covered 早于 woke up，两个时间层次有清楚参照。不能仅因都是昨晚的事就把所有动词写成过去完成时。完成学习后，请用四个事件描述露营遇雨，其中一件用过去完成时回顾。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>tent</td><td>/tent/</td><td>n.</td><td>帐篷</td><td>put up a tent</td></tr><tr><td>storm</td><td>/stɔːm/</td><td>n.</td><td>暴风雨</td><td>a sudden storm</td></tr><tr><td>wet</td><td>/wet/</td><td>adj.</td><td>湿的</td><td>wet clothes</td></tr><tr><td>sleep</td><td>/sliːp/</td><td>v.</td><td>睡觉</td><td>sleep peacefully</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>put up a tent — 搭帐篷，代词用 put it up</li><li>wake up — 醒来，过去式为 woke up</li></ul><h2 id="语法讲解-过去完成时与先后关系" tabindex="-1">语法讲解：过去完成时与先后关系 <a class="header-anchor" href="#语法讲解-过去完成时与先后关系" aria-label="Permalink to &quot;语法讲解：过去完成时与先后关系&quot;">​</a></h2><p>过去完成时由 had 加过去分词构成，表示在另一个过去参照点之前发生的事。必须先建立“过去的那个时刻”，否则不宜只因事件发生得很久以前就使用 had done。before 或 after 已清楚说明先后时，一般过去时也可能成立；过去完成时则进一步强调较早的动作已完成。叙事回到主时间线后通常继续使用一般过去时。本课应用：had covered 早于 woke up，两个时间层次有清楚参照。不能仅因都是昨晚的事就把所有动词写成过去完成时。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We had covered the bags before the rain started.</p></blockquote><p>下雨前，我们已经把包盖好了。</p><p>had covered 标记较早动作，before 从句 started 给出过去参照点；bags 是受保护的物品。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>had went 错误；had 后用过去分词 gone，不能用过去式 went。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 covered、rain、dawn；听 had 的弱读，避免遗漏时间关系。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We had covered the bags before the rain started. Water still entered through the tent door. We moved to a nearby shelter at dawn.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用四个事件描述露营遇雨，其中一件用过去完成时回顾。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：had covered 标记较早动作，before 从句 started 给出过去参照点；bags 是受保护的物品。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had went 错误；had 后用过去分词 gone，不能用过去式 went。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 cover：We had ___ the bags before it rained.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> covered</p><p><strong>解析：</strong> 过去完成时要求 had 加过去分词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>他们什么时候转移到避雨处？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> At dawn.</p><p><strong>解析：</strong> 示范的最后一句明确时间，不能推断整夜都在走。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填 go：They had ___ to sleep before midnight.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> gone</p><p><strong>解析：</strong> go 的过去分词为 gone。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去完成时与先后关系。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-026">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-028">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
